sp_widget.css:
.footer-wrap{

background:
linear-gradient(
135deg,
#081A63,
#2B58F4
);

border-radius:32px;

padding:48px;

display:grid;

grid-template-columns:
1.2fr 1fr 1fr;

gap:48px;

color:white;

position:relative;

box-shadow:
0 22px 50px
rgba(0,0,0,.12);

margin-top:20px !important;


/* FIX EMPTY SPACE */

height:auto;

min-height:unset;

align-items:start;

overflow:hidden;

}



/* DECORATION */

.footer-wrap::after{

content:'';

position:absolute;

right:-80px;

top:-80px;

width:260px;

height:260px;

border-radius:50%;

background:
rgba(255,255,255,.06);

pointer-events:none;

}



/* BRAND */

.brand{

font-size:31px;

font-weight:900;

margin-bottom:14px;

line-height:1.1;

}



.tag{

font-size:13px;

line-height:1.8;

opacity:.90;

max-width:300px;

}



/* TITLES */

.title{

font-size:17px;

font-weight:800;

margin-bottom:20px;

}



/* LINKS */

.footer-section a{

display:block;

color:white;

margin-bottom:14px;

text-decoration:none;

opacity:.88;

font-size:13px;

transition:.25s;

word-break:break-word;

}


.footer-section a:hover{

opacity:1;

transform:
translateX(5px);

}



/* META */

.meta{

margin-bottom:14px;

opacity:.85;

font-size:13px;

line-height:1.7;

}



/* LAPTOP */

@media(max-width:1100px){

.footer-wrap{

padding:46px;

gap:34px;

}

.brand{

font-size:28px;

}

}



/* TABLET */

@media(max-width:850px){

.footer-wrap{

grid-template-columns:
1fr
1fr;

padding:40px;

gap:34px;

}

.footer-section:first-child{

grid-column:
1 / -1;

}

.brand{

font-size:26px;

}

.tag{

max-width:100%;

}

}



/* MOBILE */

@media(max-width:600px){

.footer-wrap{

grid-template-columns:
1fr;

padding:32px 24px;

gap:30px;

border-radius:24px;

margin-top:36px;

text-align:center;

}

.footer-section{

display:flex;

flex-direction:column;

align-items:center;

}

.brand{

font-size:24px;

margin-bottom:10px;

}

.tag{

font-size:12px;

line-height:1.7;

}

.title{

font-size:15px;

margin-bottom:16px;

}

.footer-section a{

font-size:12px;

margin-bottom:12px;

}

.meta{

font-size:12px;

margin-bottom:12px;

}

.footer-wrap::after{

width:180px;

height:180px;

right:-60px;

top:-60px;

}

}
.footer-wrap{

margin-top:20px !important;

}
.footer-section{

align-self:start;

}
